		return CkPublicKey_SaveDerFile($this->_cPtr,$preferPkcs1,$path);
	}

	/**
	 * Saves the public key to ARG2 in PEM format. ARG1 selects the representation and PEM label using the same rules described for GetPem. The generated file uses CRLF line endings, Base64 body lines of at most 64 characters, and a final CRLF. An existing destination file is overwritten. If this object is empty, the method fails without creating the file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPublicKeyRef.html#SavePemFile
	 * @param bool $preferPkcs1
	 * @param ?string $path
	 * @return bool
	 */
	function SavePemFile($preferPkcs1,$path) {
		return CkPublicKey_SavePemFile($this->_cPtr,$preferPkcs1,$path);
	}

	/**
	 * Saves the public key to the local filesystem path specified by ARG1 using exactly the same key-type-specific XML text returned by GetXml. No additional BOM or line ending is added. An existing destination file is overwritten. If this object is empty, the method fails without creating the destination file. Choosing a file format: Use XML when another Chilkat application will read the key. For broader interoperability, PEM or DER is usually a better choice.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkPublicKeyRef.html#SaveXmlFile
	 * @param ?string $path
	 * @return bool
	 */
	function SaveXmlFile($path) {
		return CkPublicKey_SaveXmlFile($this->_cPtr,$path);
	}
}
